// --- Helpers ---------------------------------------------------------------

function doc_h(string $s): string {
    return htmlspecialchars($s, ENT_QUOTES, 'UTF-8');
}

/** Both map files must still reference the Illuminate\\ prefix. */
function doc_autoload_maps_ok(): bool {
    foreach (['autoload_psr4.php', 'autoload_static.php'] as $name) {
        $map = ROOT . '/vendor/composer/' . $name;
        if (!is_file($map)) {
            return false;
        }
        $head = @file_get_contents($map, false, null, 0, 65536);
        if ($head === false || !str_contains($head, "'Illuminate\\\\'")) {
            return false;
        }
    }
    return true;
}

/** The framework entry class must physically exist on disk. */
function doc_framework_ok(): bool {
    return is_file(ROOT . '/vendor/laravel/framework/src/Illuminate/Foundation/Application.php');
}

function doc_opcache_forget(string $file): void {
    if (function_exists('opcache_invalidate')) {
        @opcache_invalidate($file, true);
    }
}

/**
 * Return pristine Composer files from the on-disk backup, or from the bundle
 * embedded in this one doctor.php file when the old deployment has no backup.
 *
 * @return array<string, string>
 */
function doc_recovery_files(): array {
    $backupDir = ROOT . '/bootstrap/autoload_backup';
    $files = [];

    foreach (glob($backupDir . '/*.php') ?: [] as $path) {
        $content = @file_get_contents($path);
        if ($content !== false) {
            $files[basename($path)] = $content;
        }
    }
    if (isset($files['autoload.php'], $files['autoload_psr4.php'], $files['autoload_static.php'])) {
        return $files;
    }

    $encoded = str_replace(["\r", "\n"], '', DOCTOR_BUNDLE_BASE64);
    $compressed = base64_decode($encoded, true);
    if ($compressed === false || !hash_equals(DOCTOR_BUNDLE_SHA256, hash('sha256', $compressed))) {
        throw new RuntimeException('The recovery data embedded in doctor.php is corrupt; upload a fresh copy.');
    }
    $json = function_exists('gzdecode') ? @gzdecode($compressed) : false;
    if ($json === false) {
        throw new RuntimeException('PHP zlib/gzdecode is unavailable; enable zlib or perform a full deployment.');
    }
    try {
        $decoded = json_decode($json, true, 32, JSON_THROW_ON_ERROR);
    } catch (JsonException $e) {
        throw new RuntimeException('The embedded recovery data is invalid: ' . $e->getMessage(), 0, $e);
    }
    if (!is_array($decoded)) {
        throw new RuntimeException('The embedded recovery data has the wrong format.');
    }
    return $decoded;
}

/** Atomically write one recovery file so a request never sees a partial map. */
function doc_atomic_write(string $destination, string $content): bool {
    $temporary = $destination . '.doctor-' . bin2hex(random_bytes(4)) . '.tmp';
    if (@file_put_contents($temporary, $content, LOCK_EX) !== strlen($content)) {
        @unlink($temporary);
        return false;
    }
    @chmod($temporary, 0644);
    if (!@rename($temporary, $destination)) {
        @unlink($temporary);
        return false;
    }
    return true;
}

/** Restore Composer's loader and generated maps. Returns [copied[], failed[]]. */
function doc_restore_autoload(): array {
    $composerDir = ROOT . '/vendor/composer';
    if (!is_dir($composerDir) && !@mkdir($composerDir, 0775, true)) {
        return [[], ['cannot create vendor/composer/']];
    }

    try {
        $files = doc_recovery_files();
    } catch (Throwable $e) {
        return [[], [$e->getMessage()]];
    }

    $allowed = [
        'ClassLoader.php', 'InstalledVersions.php',
        'autoload_classmap.php', 'autoload_files.php', 'autoload_namespaces.php',
        'autoload_psr4.php', 'autoload_real.php', 'autoload_static.php',
        'installed.php', 'platform_check.php',
        // Publish the top-level entry point last after all of its dependencies.
        'autoload.php',
    ];
    $copied = [];
    $failed = [];
    foreach ($allowed as $file) {
        if ($file === 'autoload.php' && $failed !== []) {
            $failed[] = 'autoload.php (not published because a dependency failed)';
            continue;
        }
        if (!isset($files[$file]) || !is_string($files[$file])) {
            $failed[] = $file . ' (missing from recovery data)';
            continue;
        }
        $destination = $file === 'autoload.php'
            ? ROOT . '/vendor/autoload.php'
            : $composerDir . '/' . $file;
        if (doc_atomic_write($destination, $files[$file])) {
            doc_opcache_forget($destination);
            $copied[] = $file;
        } else {
            $failed[] = $file . ' (not writable)';
        }
    }
    if (function_exists('opcache_reset')) {
        @opcache_reset();
    }
    return [$copied, $failed];
}

/**
 * Safely probe whether Laravel can boot. Returns ['ok' => bool, 'msg' => string].
 * It does not mutate files: a broken map is reported and the authenticated
 * operator can explicitly run the restore action.
 */
function doc_probe_boot(): array {
    if (!is_file(ROOT . '/vendor/autoload.php')) {
        return ['ok' => false, 'msg' => 'vendor/autoload.php is missing.'];
    }
    if (!doc_framework_ok()) {
        return ['ok' => false, 'msg' => 'Laravel framework files are missing from vendor/.'];
    }

    if (!doc_autoload_maps_ok()) {
        return ['ok' => false, 'msg' => 'Composer autoloader maps are damaged. Use Restore autoloader below.'];
    }

    doc_opcache_forget(ROOT . '/vendor/autoload.php');

    try {
        require ROOT . '/vendor/autoload.php';
    } catch (Throwable $e) {
        return ['ok' => false, 'msg' => 'Requiring vendor/autoload.php failed: ' . $e->getMessage()];
    }

    if (!class_exists('Illuminate\Foundation\Application')) {
        return ['ok' => false, 'msg' => 'Autoloader loaded but Illuminate\Foundation\Application is still not found — stale OPcache is the likely cause (wait ~1 min and retry, or ask Hostinger to flush OPcache).'];
    }

    if (!is_file(ROOT . '/.env')) {
        return ['ok' => false, 'msg' => '.env is missing — run the installer (install.php) or create it from .env.example.'];
    }

    try {
        $app = require ROOT . '/bootstrap/app.php';
        $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class);
        $kernel->bootstrap();
        return ['ok' => true, 'msg' => 'Laravel boots successfully.'];
    } catch (Throwable $e) {
        return ['ok' => false, 'msg' => get_class($e) . ': ' . $e->getMessage()];
    }
}

// Tests may load the dependency-free recovery library without starting an HTTP
// session. This is CLI-only and cannot bypass web authentication.
if (PHP_SAPI === 'cli' && defined('HUVANTI_DOCTOR_LIBRARY_ONLY')) {
    return;
}

// --- Access control ---------------------------------------------------------

/** @return list<string> */
function doc_access_keys(): array {
    $keys = [];
    foreach (@file(ROOT . '/.env', FILE_IGNORE_NEW_LINES) ?: [] as $line) {
        if (preg_match('/^APP_KEY=(.*)$/', trim($line), $match)) {
            $value = trim(trim($match[1]), "\"'");
            if ($value !== '') {
                $keys[] = $value;
            }
            break;
        }
    }
    $recoveryKey = @file_get_contents(ROOT . '/.doctor-key');
    if ($recoveryKey !== false && trim($recoveryKey) !== '') {
        $keys[] = trim($recoveryKey);
    }
    return $keys;
}

function doc_valid_access_key(string $candidate): bool {
    foreach (doc_access_keys() as $expected) {
        if (hash_equals($expected, $candidate)) {
            return true;
        }
    }
    return false;
}

function doc_locked_page(bool $failed, bool $hasKey): never {
    http_response_code($failed ? 403 : 401);
    $message = $failed
        ? '<p class="error">That recovery key was not accepted.</p>'
        : '';
    $setup = $hasKey
        ? '<p>Enter the exact <code>APP_KEY</code> value from <code>public_html/.env</code>. You can view it only in hPanel File Manager.</p>'
        : '<p>No access key exists yet. In hPanel File Manager, create <code>public_html/.doctor-key</code> containing a long random password, then reload this page.</p>';
    $csrf = doc_h((string) ($_SESSION['doctor_csrf'] ?? ''));
    echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Unlock Huvanti Doctor</title><style>body{font:16px/1.55 system-ui,sans-serif;background:#fafafa;color:#1c1b1f;margin:0}.card{max-width:520px;margin:8vh auto;background:#fff;border:1px solid #ddd;border-radius:12px;padding:26px;box-shadow:0 2px 10px #0001}h1{font-size:24px;margin:0 0 8px}p{color:#555}code{background:#f3f3f5;padding:2px 5px;border-radius:4px}label{display:block;font-weight:600;margin-top:18px}input{box-sizing:border-box;width:100%;padding:12px;margin-top:6px;border:1px solid #aaa;border-radius:8px;font-size:16px}button{width:100%;margin-top:16px;padding:12px;border:0;border-radius:8px;background:#1565c0;color:#fff;font-size:16px;font-weight:650}.error{padding:10px;background:#fef2f2;color:#991b1b;border-radius:8px}.build{font-size:12px;color:#777;margin-top:20px}</style></head><body><main class="card"><h1>Huvanti Doctor is locked</h1><p>Recovery diagnostics can expose server details and run migrations, so authentication is required.</p>' . $message . $setup . '<form method="post"><input type="hidden" name="csrf" value="' . $csrf . '"><input type="hidden" name="action" value="unlock"><label for="recovery_key">Recovery key</label><input id="recovery_key" name="recovery_key" type="password" autocomplete="current-password" required autofocus><button type="submit">Unlock doctor</button></form><p class="build">Deployment: ' . doc_h(DOCTOR_DEPLOYMENT) . '</p></main></body></html>';
    exit;
}

header('Cache-Control: no-store, max-age=0');
header('X-Robots-Tag: noindex, nofollow');
header('X-Frame-Options: DENY');
header('X-Content-Type-Options: nosniff');
header('X-Huvanti-Deploy: ' . DOCTOR_DEPLOYMENT);

if (!@session_start([
    'use_strict_mode' => true,
    'cookie_httponly' => true,
    'cookie_secure' => (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off'),
    'cookie_samesite' => 'Strict',
])) {
    http_response_code(500);
    exit('Huvanti Doctor cannot start a secure session. Check PHP session.save_path permissions.');
}
if (empty($_SESSION['doctor_csrf'])) {
    $_SESSION['doctor_csrf'] = bin2hex(random_bytes(24));
}

$requestMethod = $_SERVER['REQUEST_METHOD'] ?? 'GET';
$action = is_string($_POST['action'] ?? null) ? $_POST['action'] : '';
$csrfValid = $requestMethod === 'POST'
    && hash_equals((string) $_SESSION['doctor_csrf'], (string) ($_POST['csrf'] ?? ''));

if (empty($_SESSION['doctor_authorized'])) {
    $unlockFailed = false;
    if ($requestMethod === 'POST' && $action === 'unlock') {
        $candidate = (string) ($_POST['recovery_key'] ?? '');
        if ($csrfValid && doc_valid_access_key($candidate)) {
            session_regenerate_id(true);
            $_SESSION['doctor_authorized'] = true;
            $_SESSION['doctor_csrf'] = bin2hex(random_bytes(24));
            header('Location: ' . strtok($_SERVER['REQUEST_URI'] ?? '/doctor.php', '?'));
            exit;
        }
        usleep(750000);
        $unlockFailed = true;
    }
    doc_locked_page($unlockFailed, doc_access_keys() !== []);
}

// --- Run an authenticated POST action --------------------------------------

$messages = [];
$actionErrors = [];
$migLog = '';
$csrf = (string) $_SESSION['doctor_csrf'];

if ($requestMethod === 'POST') {
    if (!$csrfValid) {
        $actionErrors[] = 'Security token expired or invalid. Reload this page and try again.';
        $action = '';
    }

    if ($action === 'restore_autoload') {
        [$copied, $failed] = doc_restore_autoload();
        if ($failed) {
            $actionErrors[] = 'Restore failed: ' . implode(', ', $failed);
        } elseif (!doc_autoload_maps_ok()) {
            $actionErrors[] = 'Files copied but maps still look wrong — a full re-deploy is needed.';
        } else {
            $messages[] = 'Autoloader restored (' . count($copied) . ' verified Composer files written, OPcache flushed). Reload the homepage.';
            if (!doc_framework_ok()) {
                $actionErrors[] = 'Maps are restored, but framework files are still missing from vendor/ — delete vendor/ in File Manager and re-deploy from Git.';
            }
        }
    }

    if ($action === 'migrate') {
        $probe = doc_probe_boot();
        if (!$probe['ok']) {
            $actionErrors[] = 'Cannot migrate — Laravel will not boot: ' . $probe['msg'];
        } else {
            try {
                $app = require ROOT . '/bootstrap/app.php';
                $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
                Illuminate\Support\Facades\Artisan::call('migrate', ['--force' => true]);
                $migLog = Illuminate\Support\Facades\Artisan::output();
                $messages[] = 'Pending migrations applied.';
            } catch (Throwable $e) {
                $actionErrors[] = 'Migration failed: ' . $e->getMessage();
            }
        }
    }

    if ($action === 'clear_caches') {
        foreach ([
            ROOT . '/bootstrap/cache/config.php',
            ROOT . '/bootstrap/cache/routes.php',
            ROOT . '/bootstrap/cache/events.php',
            ROOT . '/bootstrap/cache/compiled.php',
        ] as $f) {
            if (is_file($f)) {
                @unlink($f);
            }
        }
        // Clear framework view cache.
        foreach (glob(ROOT . '/storage/framework/views/*.php') ?: [] as $f) {
            @unlink($f);
        }
        $messages[] = 'Cleared bootstrap/cache compiled files + view cache.';
    }

    if ($action === 'delete_self') {
        // Best-effort self-delete, then redirect to homepage.
        @unlink(__FILE__);
        header('Location: /');
        exit;
    }
}

