if (is_file(ROOT . '/.env')) {
    $env = parse_ini_file(ROOT . '/.env', false, INI_SCANNER_RAW) ?: [];
    $conn = $env['DB_CONNECTION'] ?? '';
    if (($conn === 'mysql') && !empty($env['DB_HOST']) && !empty($env['DB_DATABASE']) && !empty($env['DB_USERNAME'])) {
        try {
