                $env['DB_HOST'], (int)($env['DB_PORT'] ?? 3306), $env['DB_DATABASE']);
            $pdo = new PDO($dsn, $env['DB_USERNAME'], (string)($env['DB_PASSWORD'] ?? ''), [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_TIMEOUT => 5,
